  private readonly studentContentCache=new Map<string,{updatedAt:string;content:any}>();
  constructor(@Inject(QuestionBankService) private readonly bank: QuestionBankService,@Inject(MediaStorageService) private readonly mediaStorage:MediaStorageService) {}
  private async ensureReviewSchema(){await query(`ALTER TABLE chapter_library ADD COLUMN IF NOT EXISTS reviewer_id UUID REFERENCES app_user(user_id) ON DELETE SET NULL, ADD COLUMN IF NOT EXISTS submitted_for_review_at TIMESTAMPTZ, ADD COLUMN IF NOT EXISTS submitted_by UUID REFERENCES app_user(user_id) ON DELETE SET NULL; CREATE TABLE IF NOT EXISTS chapter_review_audit (audit_id UUID PRIMARY KEY, chapter_id UUID NOT NULL REFERENCES chapter_library(chapter_id) ON DELETE CASCADE, actor_id UUID REFERENCES app_user(user_id) ON DELETE SET NULL, action VARCHAR(60) NOT NULL, area VARCHAR(40) NOT NULL, summary TEXT NOT NULL, details JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_chapter_review_audit_chapter ON chapter_review_audit(chapter_id,created_at DESC)`)}
  private async audit(chapterId:string,user:any,action:string,area:string,summary:string,details:any={}){await this.ensureReviewSchema();await query(`INSERT INTO chapter_review_audit(audit_id,chapter_id,actor_id,action,area,summary,details) VALUES($1,$2,$3,$4,$5,$6,$7::jsonb)`,[randomUUID(),chapterId,user?.id||null,action,area,summary,JSON.stringify(details)])}
  private async ensureReviewItemsSchema(){await this.ensureReviewSchema();await query(`CREATE TABLE IF NOT EXISTS chapter_review_item (review_item_id UUID PRIMARY KEY, chapter_id UUID NOT NULL REFERENCES chapter_library(chapter_id) ON DELETE CASCADE, item_key TEXT NOT NULL, area VARCHAR(40) NOT NULL, label TEXT NOT NULL, approved BOOLEAN NOT NULL DEFAULT false, comment TEXT NOT NULL DEFAULT '', reviewer_id UUID REFERENCES app_user(user_id) ON DELETE SET NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(chapter_id,item_key)); CREATE INDEX IF NOT EXISTS idx_chapter_review_item_chapter ON chapter_review_item(chapter_id,area)`) }
  async assertReviewAccess(chapterId:string,user:any){if(user?.role!=='reviewer')return;await this.ensureReviewSchema();const r=await query(`SELECT 1 FROM chapter_library WHERE chapter_id=$1 AND reviewer_id=$2`,[chapterId,user.id]);if(!r.rowCount)throw new ForbiddenException('This chapter is not assigned to you for review')}
  async assertReviewMutation(chapterId:string,user:any){await this.assertReviewAccess(chapterId,user);if(user?.role==='reviewer')return;const r=await query(`SELECT status FROM chapter_library WHERE chapter_id=$1`,[chapterId]);if(r.rowCount&&['in_review','reviewed'].includes(r.rows[0].status))throw new ForbiddenException('This chapter is locked while it is with the reviewer or awaiting Admin approval')}
  async assertChapterMedia(chapterId:string,mediaId:string){const r=await query(`SELECT 1 FROM media_asset WHERE media_id=$1 AND chapter_id=$2`,[mediaId,chapterId]);if(!r.rowCount)throw new NotFoundException('Image not found in this chapter')}
  private studentContent(chapterId:string,updatedAt:any,content:any){const version=String(updatedAt||''),cached=this.studentContentCache.get(chapterId);if(cached?.updatedAt===version)return cached.content;const json=JSON.stringify(content||{}).replace(/data:(image\/[a-z0-9.+-]+);base64,([a-z0-9+/=]+)/gi,(_match,mimeType,data)=>{const buffer=Buffer.from(data,'base64'),hash=createHash('sha256').update(buffer).digest('hex');this.embeddedImages.set(`${chapterId}:${hash}`,{buffer,mimeType});return `/api/catalogue/chapters/${chapterId}/embedded-images/${hash}`}),result=JSON.parse(json);this.studentContentCache.set(chapterId,{updatedAt:version,content:result});if(this.embeddedImages.size>200){const oldest=this.embeddedImages.keys().next().value;if(oldest)this.embeddedImages.delete(oldest)}return result}
