  private async ensureOfferingSchema() { await query(`ALTER TABLE course_offering ADD COLUMN IF NOT EXISTS validity_mode VARCHAR(20) NOT NULL DEFAULT 'duration', ADD COLUMN IF NOT EXISTS validity_value INTEGER, ADD COLUMN IF NOT EXISTS validity_unit VARCHAR(10), ADD COLUMN IF NOT EXISTS validity_start_date DATE, ADD COLUMN IF NOT EXISTS validity_end_date DATE, ADD COLUMN IF NOT EXISTS free_trial_days INTEGER NOT NULL DEFAULT 0`); }
