  async listChapters(user?:any) { await this.ensureReviewSchema();const values=user?.role==='reviewer'?[user.id]:[],where=user?.role==='reviewer'?`WHERE c.reviewer_id=$1 AND c.status IN ('in_review','reviewed')`:'';const r=await query(`SELECT c.*,u.display_name reviewer_name,u.email reviewer_email FROM chapter_library c LEFT JOIN app_user u ON u.user_id=c.reviewer_id ${where} ORDER BY c.updated_at DESC`,values); return r.rows.map(row=>{const chapter=chapterRow(row),safePackage=chapter.package?{...chapter.package,content:undefined,cycleTest:studentCycleTest(chapter.package.cycleTest)}:undefined;return {...chapter,content:this.studentContent(chapter.id,chapter.updatedAt,chapter.content),package:safePackage};}); }
  async getChapter(id:string,user?:any) { await this.ensureReviewSchema();await this.assertReviewAccess(id,user);const r=await query('SELECT c.*,u.display_name reviewer_name,u.email reviewer_email FROM chapter_library c LEFT JOIN app_user u ON u.user_id=c.reviewer_id WHERE c.chapter_id=$1',[id]); if(!r.rowCount) throw new NotFoundException('Chapter not found'); return chapterRow(r.rows[0]); }
  async reviewers(){await this.ensureReviewSchema();const r=await query(`SELECT user_id id,email,display_name "displayName" FROM app_user WHERE role='reviewer' AND status='active' ORDER BY display_name`);return r.rows}
  async assignReviewer(id:string,reviewerId:string,user:any){await this.ensureReviewSchema();const reviewer=await query(`SELECT user_id,display_name,email FROM app_user WHERE user_id=$1 AND role='reviewer' AND status='active'`,[reviewerId]);if(!reviewer.rowCount)throw new UnprocessableEntityException('Select an active reviewer');const r=await query(`UPDATE chapter_library SET reviewer_id=$2,updated_at=now() WHERE chapter_id=$1 RETURNING *`,[id,reviewerId]);if(!r.rowCount)throw new NotFoundException('Chapter not found');await this.audit(id,user,'reviewer_assigned','workflow',`Assigned reviewer ${reviewer.rows[0].display_name}`,{reviewerId});return this.getChapter(id)}
  async submitForReview(id:string,user:any){await this.ensureReviewItemsSchema();const current=await this.getChapter(id);if(!current.reviewer?.id)throw new UnprocessableEntityException('Assign a reviewer before submitting');const r=await query(`UPDATE chapter_library SET status='in_review',submitted_for_review_at=now(),submitted_by=$2,updated_at=now() WHERE chapter_id=$1 RETURNING *`,[id,user.id]);await query(`DELETE FROM chapter_review_item WHERE chapter_id=$1`,[id]);await this.audit(id,user,'submitted_for_review','workflow',`Submitted version ${current.version} for review`,{version:current.version,reviewerId:current.reviewer.id});return chapterRow(r.rows[0])}
  async reviewAudit(id:string,user:any){await this.assertReviewAccess(id,user);await this.ensureReviewSchema();const r=await query(`SELECT a.audit_id id,a.action,a.area,a.summary,a.details,a.created_at "createdAt",u.display_name "actorName",u.role "actorRole" FROM chapter_review_audit a LEFT JOIN app_user u ON u.user_id=a.actor_id WHERE a.chapter_id=$1 ORDER BY a.created_at DESC`,[id]);return r.rows}
  async reviewItems(id:string,user:any){await this.assertReviewAccess(id,user);await this.ensureReviewItemsSchema();const r=await query(`SELECT item_key "itemKey",area,label,approved,comment,updated_at "updatedAt" FROM chapter_review_item WHERE chapter_id=$1 ORDER BY area,label`,[id]);return r.rows}
  async saveReviewItem(id:string,itemKey:string,body:any,user:any){if(user?.role!=='reviewer')throw new ForbiddenException('Only the assigned reviewer can record review decisions');await this.assertReviewAccess(id,user);await this.ensureReviewItemsSchema();const area=String(body.area||'content').slice(0,40),label=String(body.label||itemKey).slice(0,500),comment=String(body.comment||'').slice(0,4000),approved=Boolean(body.approved);const r=await query(`INSERT INTO chapter_review_item(review_item_id,chapter_id,item_key,area,label,approved,comment,reviewer_id) VALUES($1,$2,$3,$4,$5,$6,$7,$8) ON CONFLICT(chapter_id,item_key) DO UPDATE SET area=excluded.area,label=excluded.label,approved=excluded.approved,comment=excluded.comment,reviewer_id=excluded.reviewer_id,updated_at=now() RETURNING item_key "itemKey",area,label,approved,comment,updated_at "updatedAt"`,[randomUUID(),id,itemKey,area,label,approved,comment,user.id]);await this.audit(id,user,'review_item_updated',area,`${approved?'Approved':'Reviewed'}: ${label}`,{itemKey,approved,hasComment:Boolean(comment)});return r.rows[0]}
  async approveAllReviewItems(id:string,body:any,user:any){if(user?.role!=='reviewer')throw new ForbiddenException('Only the assigned reviewer can record review decisions');await this.assertReviewAccess(id,user);await this.ensureReviewItemsSchema();const items=Array.isArray(body.items)?body.items:[];for(const item of items)await query(`INSERT INTO chapter_review_item(review_item_id,chapter_id,item_key,area,label,approved,comment,reviewer_id) VALUES($1,$2,$3,$4,$5,true,$6,$7) ON CONFLICT(chapter_id,item_key) DO UPDATE SET area=excluded.area,label=excluded.label,approved=true,reviewer_id=excluded.reviewer_id,updated_at=now()`,[randomUUID(),id,String(item.itemKey),String(item.area||'content').slice(0,40),String(item.label||item.itemKey).slice(0,500),String(item.comment||'').slice(0,4000),user.id]);await this.audit(id,user,'review_items_approved_all','workflow',`Approved all ${items.length} review items`,{count:items.length});return this.reviewItems(id,user)}
  async chapterMedia(id:string) { const chapter=await this.getChapter(id),blockRefs=(chapter.content?.topics||[]).flatMap((topic:any)=>[...(topic.introductionPages||[]),...(topic.subtopics||[]).flatMap((sub:any)=>sub.pages||[])]).flatMap((page:any)=>(page.blocks||[]).filter((block:any)=>block.type==='image').map((block:any)=>block.mediaRef)),names=[...(chapter.package?.mediaManifest||[]).map((item:any)=>item.fileName),...blockRefs],roots=names.map((name:string)=>name.toLowerCase().replace(/\.(png|jpe?g|webp|svg)$/,'')); const r=await query(`SELECT DISTINCT ON (original_name) media_id,original_name,file_name,title,caption,alt_text,stored_name,storage_provider,object_key FROM media_asset WHERE chapter_id=$1 OR lower(regexp_replace(original_name,'\\.(png|jpe?g|webp|svg)$','','i'))=ANY($2::text[]) ORDER BY original_name,created_at DESC`,[id,roots]); return r.rows.map((x:any)=>({id:x.media_id,fileName:x.file_name,title:x.title,caption:x.caption,altText:x.alt_text,url:this.mediaStorage.url(x)})); }
