  async deleteSubject(id:string) {
    const subject=await this.getSubject(id);
    const linked=await query<{title:string}>('SELECT o.title FROM course_offering_subject cs JOIN course_offering o ON o.offering_id=cs.offering_id WHERE cs.subject_id=$1 ORDER BY o.title',[id]);
    if(linked.rowCount)throw new UnprocessableEntityException(`Remove this subject from the following course offering(s) before deleting it: ${linked.rows.map(row=>row.title).join(', ')}`);
    const result=await query('DELETE FROM subject_definition WHERE subject_id=$1',[id]);
    if(!result.rowCount)throw new NotFoundException('Subject not found');
    return {deleted:true,id,title:subject.title,deletedUnits:subject.units.length};
  }
