  async addChapterToUnit(subjectId:string,unitId:string,body:any) { const chapter=await this.getChapter(required(body.chapterId,'chapterId')); if(chapter.status!=='approved') throw new UnprocessableEntityException('Only approved chapters can be added to a subject'); const check=await query('SELECT 1 FROM subject_unit WHERE unit_id=$1 AND subject_id=$2',[unitId,subjectId]); if(!check.rowCount) throw new NotFoundException('Unit not found'); const position=body.position||((await query<{max:number}>('SELECT COALESCE(MAX(position),0) max FROM unit_chapter WHERE unit_id=$1',[unitId])).rows[0].max+1); await query('INSERT INTO unit_chapter(unit_id,chapter_id,position) VALUES($1,$2,$3) ON CONFLICT(unit_id,chapter_id) DO UPDATE SET position=EXCLUDED.position',[unitId,chapter.id,position]); return this.getSubject(subjectId); }
