  async adminDashboard(){await this.ensureEnrolmentSchema();const [summary,courseRows,subjectRows]=await Promise.all([query(`SELECT (SELECT COUNT(*) FROM chapter_library)::int chapters,(SELECT COUNT(*) FROM subject_definition)::int subjects,(SELECT COUNT(*) FROM subject_definition WHERE status='approved')::int published_subjects,(SELECT COUNT(*) FROM course_offering)::int courses,(SELECT COUNT(*) FROM course_offering WHERE status='published')::int published_courses,(SELECT COUNT(*) FROM course_enrolment WHERE status='active' AND (expires_at IS NULL OR expires_at>now()))::int active_subscribers,(SELECT COUNT(*) FROM course_enrolment WHERE status='expired' OR expires_at IS NOT NULL AND expires_at<=now())::int expired_subscriptions`),query(`SELECT o.offering_id id,o.title,o.status,COUNT(e.enrolment_id) FILTER (WHERE e.status='active' AND (e.expires_at IS NULL OR e.expires_at>now()))::int active_subscribers,COUNT(e.enrolment_id) FILTER (WHERE e.status='expired' OR e.expires_at IS NOT NULL AND e.expires_at<=now())::int expired_subscriptions FROM course_offering o LEFT JOIN course_enrolment e ON e.offering_id=o.offering_id GROUP BY o.offering_id ORDER BY o.updated_at DESC`),query(`SELECT s.subject_id id,s.title,s.status,COALESCE(json_agg(json_build_object('id',c.chapter_id,'title',c.title,'position',uc.position,'unit',u.title,'status',c.status) ORDER BY u.position,uc.position) FILTER (WHERE c.chapter_id IS NOT NULL),'[]') chapters FROM subject_definition s LEFT JOIN subject_unit u ON u.subject_id=s.subject_id LEFT JOIN unit_chapter uc ON uc.unit_id=u.unit_id LEFT JOIN chapter_library c ON c.chapter_id=uc.chapter_id GROUP BY s.subject_id ORDER BY s.updated_at DESC`)]);const row=summary.rows[0];return {summary:{chapters:row.chapters,subjects:row.subjects,publishedSubjects:row.published_subjects,courses:row.courses,publishedCourses:row.published_courses,activeSubscribers:row.active_subscribers,expiredSubscriptions:row.expired_subscriptions},courses:courseRows.rows.map((course:any)=>({...course,activeSubscribers:Number(course.active_subscribers),expiredSubscriptions:Number(course.expired_subscriptions)})),subjects:subjectRows.rows};}
